/**
 * Assemble everything the live server needs, and nothing it does not.
 *
 *   npm run build
 *   npm run deploy:bundle
 *
 * Produces `deploy/ibcr-app/` and `deploy/ibcr-app.zip`. Upload the zip to the
 * hosting account, extract it, and the folder that appears is a complete
 * application root: see DEPLOY.md.
 *
 * What is left out matters as much as what goes in:
 *   - `node_modules` — the host installs its own with "Run NPM Install", into
 *     the Node virtual environment it manages. Uploading ours would be shadowed.
 *   - `.next/cache` — build cache, about 65 MB, rebuilt as needed and never read
 *     by the running server.
 *   - `src`, `tools`, config for lint/TypeScript — build-time only.
 *
 * The generated package.json pins every dependency to the exact version this
 * build was made against, so the server installs what was tested rather than
 * whatever the range resolves to on the day.
 */
import { execFileSync } from "node:child_process";
import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
const out = path.join(root, "deploy");
const appDir = path.join(out, "ibcr-app");
const zipPath = path.join(out, "ibcr-app.zip");

/** Parts of `.next` the running server never reads. */
const SKIP_IN_NEXT = new Set(["cache", "trace", "trace-build", "diagnostics"]);

/** Needed by server.js directly; normally hoisted, pinned so it always resolves. */
const EXTRA_DEPENDENCIES = ["@next/env"];

function die(message) {
  console.error(`\n✗ ${message}\n`);
  process.exit(1);
}

function installedVersion(name) {
  const file = path.join(root, "node_modules", name, "package.json");
  if (!fs.existsSync(file)) die(`${name} is not installed — run npm install first.`);
  return JSON.parse(fs.readFileSync(file, "utf8")).version;
}

function mb(bytes) {
  return `${(bytes / 1024 / 1024).toFixed(1)} MB`;
}

function sizeOf(target) {
  const stat = fs.statSync(target);
  if (!stat.isDirectory()) return stat.size;
  return fs
    .readdirSync(target)
    .reduce((total, entry) => total + sizeOf(path.join(target, entry)), 0);
}

// ----------------------------------------------------------------- checks
if (!fs.existsSync(path.join(root, ".next", "BUILD_ID"))) {
  die("No production build found. Run `npm run build` first.");
}

const pkg = JSON.parse(fs.readFileSync(path.join(root, "package.json"), "utf8"));

// ------------------------------------------------------------------ copy
fs.rmSync(appDir, { recursive: true, force: true });
fs.mkdirSync(appDir, { recursive: true });

const nextSrc = path.join(root, ".next");
fs.cpSync(nextSrc, path.join(appDir, ".next"), {
  recursive: true,
  filter: (src) => {
    const relative = path.relative(nextSrc, src);
    if (!relative) return true;
    return !SKIP_IN_NEXT.has(relative.split(path.sep)[0]);
  },
});

fs.cpSync(path.join(root, "public"), path.join(appDir, "public"), { recursive: true });

for (const file of ["server.js", "next.config.ts"]) {
  fs.copyFileSync(path.join(root, file), path.join(appDir, file));
}

// --------------------------------------------------- runtime package.json
const dependencies = {};
for (const name of [...Object.keys(pkg.dependencies), ...EXTRA_DEPENDENCIES].sort()) {
  dependencies[name] = installedVersion(name);
}

fs.writeFileSync(
  path.join(appDir, "package.json"),
  `${JSON.stringify(
    {
      name: pkg.name,
      version: pkg.version,
      private: true,
      description: "IBCR website — built output, ready to run. Generated by npm run deploy:bundle.",
      engines: { node: ">=20.9.0" },
      scripts: { start: "node server.js" },
      dependencies,
    },
    null,
    2,
  )}\n`,
);

fs.copyFileSync(path.join(root, "DEPLOY.md"), path.join(appDir, "DEPLOY.md"));

// ------------------------------------------------------------------- zip
fs.rmSync(zipPath, { force: true });
try {
  execFileSync("zip", ["-rq", zipPath, "ibcr-app"], { cwd: out });
} catch {
  die("`zip` is not available. Archive deploy/ibcr-app yourself, keeping the folder name.");
}

// ---------------------------------------------------------------- report
console.log("");
console.log(`  built against next ${dependencies.next}, node ${process.version}`);
console.log("");
for (const entry of [".next", "public", "server.js", "package.json"]) {
  console.log(`  ${entry.padEnd(14)} ${mb(sizeOf(path.join(appDir, entry))).padStart(9)}`);
}
console.log(`  ${"—".repeat(24)}`);
console.log(`  ${"folder".padEnd(14)} ${mb(sizeOf(appDir)).padStart(9)}`);
console.log(`  ${"zip".padEnd(14)} ${mb(sizeOf(zipPath)).padStart(9)}   deploy/ibcr-app.zip`);
console.log("");
console.log("  Next: follow DEPLOY.md. The zip extracts to a folder named ibcr-app.");
console.log("");
